    /**
     * @param array<int, array{0: string, 1: int, 2: bool}> $expectedColumns
     * @return list<object>
     */
    private function decodeRows(ExecuteQueryResult $result, string $query, array $expectedColumns, Closure $decode): array
    {
        $sets = $result->getResultSets();
        if (count($sets) !== 1) {
            throw new UnexpectedValueException(sprintf('%s: expected one YDB result set, got %d', $query, count($sets)));
        }
        $set = $sets->offsetGet(0);
        if ($set->getTruncated()) {
            throw new UnexpectedValueException($query . ': YDB result is truncated; use a bounded query or pagination');
        }

        $columns = $set->getColumns();
        if (count($columns) !== count($expectedColumns)) {
            throw new UnexpectedValueException(sprintf('%s: expected %d result columns, got %d', $query, count($expectedColumns), count($columns)));
        }
        foreach ($expectedColumns as $index => [$name, $typeId, $optional]) {
            $column = $columns->offsetGet($index);
            if ($column->getName() !== $name) {
                throw new UnexpectedValueException(sprintf('%s: result column %d is %s, expected %s', $query, $index, $column->getName(), $name));
            }
            YdbValueCodec::assertType($column->getType(), $typeId, $optional, $query . '.' . $name);
        }
        $rows = [];
        foreach ($set->getRows() as $rowIndex => $row) {
            $items = $row->getItems();
            if (count($items) !== count($expectedColumns)) {
                throw new UnexpectedValueException(sprintf('%s: row %d has %d values, expected %d', $query, $rowIndex, count($items), count($expectedColumns)));
            }
            $rows[] = $decode($items);
        }
        return $rows;
    }
